// Danciness score for Beat Saber: a port of the prototype in tools/danciness (features.py + analyze.py).
// One self-contained C# 7.3 / netstandard2.0 file with no dependencies, so the mod and the server can both compile it:
// feed it what the BeatLeader replay recorder writes for every frame, and it returns how dancy the play is, live
// (trailing 8 s, for the energy rule and the effects) and for the whole song (the leaderboard value; the server
// recomputes it from the .bsor).
//
// The measures, their weights and the vote calibration were fitted on community votes (3 rounds + 2 extra votes,
// 2026-10); since FormulaVersion 3, sway without bounce can't reach the top (BounceCm / BouncePenalty). The reference
// tables at the end of the file are generated by tools/danciness/make_tables.py; regenerate them rather than editing.
using System;
using System.Collections.Generic;
using System.Threading;

namespace BeatLeader.Dance
{
    /// <summary>A wall as a box the player has to keep the head out of: song-time seconds and metres.</summary>
    public struct DanceWall
    {
        public float StartTime, EndTime, X0, X1, Y0, Y1;

        public DanceWall(float startTime, float endTime, float x0, float x1, float y0, float y1)
        {
            StartTime = startTime; EndTime = endTime; X0 = x0; X1 = x1; Y0 = y0; Y1 = y1;
        }

        /// <summary>Wall from grid units, as the simulator places it (ReplayRecalculator/WallMovement.cs). Noodle
        /// coordinates [x, y] map to lineIndex = x + 2, lineLayer = y, and size [w, h] to width / height.</summary>
        public static DanceWall FromGrid(float time, float duration, float lineIndex, float lineLayer, float width, float height)
        {
            float x0 = (lineIndex - 2) * 0.6f, y0 = 0.1f + 0.6f * lineLayer;
            return new DanceWall(time, time + duration, x0, x0 + width * 0.6f, y0, y0 + height * 0.6f);
        }
    }

    /// <summary>The six measures the score is made of. NaN when a measure could not be computed.</summary>
    public sealed class DanceMeasures
    {
        /// <summary>Head tilt side to side, degrees (RMS, 0.3-3 Hz).</summary>
        public double Tilt;
        /// <summary>Head bounce in time with the beat, cm.</summary>
        public double BeatBounce;
        /// <summary>How locked the bounce is to the beat: power at the beat over nearby rhythms.</summary>
        public double BeatLock;
        /// <summary>Body sway the swings don't explain, cm (RMS, 0.2-3 Hz).</summary>
        public double FreeSway;
        /// <summary>Body sway, cm (RMS, 0.2-3 Hz).</summary>
        public double Sway;
        /// <summary>Average / peak head speed: steady flow is high, a few big bursts low.</summary>
        public double Steadiness;
        /// <summary>Share of the time that counted (not paused, glitching, or dodging a wall).</summary>
        public double CountedFraction;
    }

    public sealed class DanceResult
    {
        /// <summary>False when there was too little play to judge (under 30 s or 500 frames).</summary>
        public bool Valid;
        /// <summary>Danciness 0..1: the share of reference replays that score lower. The "dancing" line is about 0.945.</summary>
        public double Score;
        /// <summary>Expected share of voters who would call the play dancing, 0..1 (a calibration; it gets refit).</summary>
        public double VoteShare;
        public DanceMeasures Measures;
    }

    public struct DanceLive
    {
        /// <summary>True once a full window of play has been seen.</summary>
        public bool Ready;
        /// <summary>Danciness of the trailing window, 0..1 against reference windows.</summary>
        public double Level;
        /// <summary>Share of the window that counted (walls in the way, pauses and glitches don't).</summary>
        public double CountedFraction;
        /// <summary>The window counted enough to judge and its level is under the threshold.</summary>
        public bool ShouldDrain;
        /// <summary>Song time (seconds) of the frame the update was taken at.</summary>
        public float SongTime;
    }

    /// <summary>
    /// Feed every recorded frame with <see cref="AddFrame"/>; read <see cref="Live"/> for the energy rule and call
    /// <see cref="Finish"/> (also fine mid-song) for the score. AddFrame is O(1) and does not allocate (buffers are
    /// sized from the song length and only grow by doubling); the live update runs on a thread-pool worker from a
    /// snapshot and reuses its buffers.
    /// </summary>
    public sealed class DanceScorer
    {
        /// <summary>Bumped whenever the measures, weights or song reference tables change, so stored scores can be
        /// tagged with it and recomputed from their replays. The live level is not part of a stored score: changing
        /// the window or its tables leaves this alone.</summary>
        public const int FormulaVersion = 3;
        public const double SampleRate = 50;      // the measures are defined on a 50 Hz grid
        public const double MinSeconds = 30;      // shorter plays are not scored
        public const int MinFrames = 500;
        public const double EndSeconds = 2.5;     // level ending: players drop poses and reach for buttons
        public const double LiveWindow = 8;       // seconds of play the live level looks at (was 20 until 2026-10-31:
                                                  // a still player now shows in ~5 s instead of ~14 s; one 8 s beat block)
        public const double LiveInterval = 1;     // seconds between live updates
        public const double LiveMinCounted = 0.5; // a window mostly behind walls / paused can't be judged
        /// <summary>
        /// Suggested energy drain per second (song time) while <see cref="DanceLive.ShouldDrain"/>, with good cuts not
        /// charging energy meanwhile (a good cut gives +0.01, so a 4 notes/s map would otherwise outpace the drain).
        /// Simulated on ~3,300 replays (8 s live window, game energy rules, from the 0.5 starting energy): 20% of real
        /// dancers would fail, 82% of players voted not dancing would, at a median 25 s into the song; 4% of the
        /// dancers fail from misses alone. The mod's DNC drain is 0.05/s.
        /// </summary>
        public const double SuggestedDrainPerSecond = 0.05;

        readonly double speed;
        readonly DanceWall[] walls;
        readonly double gridPeriod;               // note grid period, real seconds (NaN if under 30 notes)
        readonly List<double> pauses = new List<double>();
        readonly List<double> jumps = new List<double>();
        FrameBuffer frames;                       // real-time seconds + 10 channels
        double lastSongTime = double.NegativeInfinity, lastLive = double.NegativeInfinity;

        // live update state: touched by the worker only while liveBusy == 1
        readonly object liveLock = new object();
        DanceLive live;
        int liveBusy;
        readonly FrameBuffer liveSnapshot = new FrameBuffer(4096);
        readonly Workspace liveWork = new Workspace();
        double[] livePauses = new double[0], liveJumps = new double[0];
        double liveNow;
        readonly WaitCallback liveCallback;

        /// <summary>Compute the live level on a thread-pool worker (default): an update costs a few ms, too much for a
        /// VR frame. Set false to compute it inline inside <see cref="AddFrame"/>.</summary>
        public bool LiveInBackground = true;

        /// <summary>Run the live level at all (default). Set false when only <see cref="Finish"/> is needed, e.g. on the
        /// server: <see cref="Live"/> then stays default. Scores don't depend on it.</summary>
        public bool LiveEnabled = true;

        /// <summary>Latest live state (updated about once a second; in the background it lands a few ms after the
        /// frame that triggered it).</summary>
        public DanceLive Live { get { lock (liveLock) return live; } }

        /// <param name="noteTimes">Song-time seconds of every note that is not a bomb (chain links included).</param>
        /// <param name="walls">Walls the player can hit (leave out fake / uninteractable ones). May be null.</param>
        /// <param name="songSpeed">Song time per real second (SF 1.5, FS 1.2, SS 0.85, practice speed).</param>
        /// <param name="songLength">Song length in song seconds, to size the frame buffers up front (0 = grow).</param>
        public DanceScorer(IList<float> noteTimes, IList<DanceWall> walls, float songSpeed = 1f, float songLength = 0f)
        {
            speed = songSpeed > 0 ? songSpeed : 1;
            this.walls = walls == null ? new DanceWall[0] : new List<DanceWall>(walls).ToArray();
            frames = new FrameBuffer(Math.Max(16384, (int)(songLength / speed * 160)));
            var real = new List<double>();
            if (noteTimes != null)
                foreach (var n in noteTimes) real.Add(n / speed);
            gridPeriod = real.Count >= 30 ? DanceMath.GridPeriod(real) : double.NaN;
            liveCallback = _ => ComputeLive();
        }

        /// <summary>One recorded frame: song time, head position and rotation (quaternion), hand positions, exactly as
        /// the replay recorder writes them. Frames may come at any rate.</summary>
        public void AddFrame(float songTime, float hx, float hy, float hz, float qx, float qy, float qz, float qw,
            float lx, float ly, float lz, float rx, float ry, float rz)
        {
            if (songTime == 0 || songTime <= lastSongTime) return; // same filtering as the replay decoder
            int n = frames.Count;
            if (n > 0)
            {
                double dx = hx - frames.Ch[0][n - 1], dy = hy - frames.Ch[1][n - 1], dz = hz - frames.Ch[2][n - 1];
                if (Math.Sqrt(dx * dx + dy * dy + dz * dz) > 0.25) jumps.Add(songTime / speed); // tracking teleport
            }
            lastSongTime = songTime;
            frames.Add(songTime / speed, hx, hy, hz, DanceMath.Roll(qx, qy, qz, qw), lx, ly, lz, rx, ry, rz);
            if (LiveEnabled && frames.T[n] - lastLive >= LiveInterval) UpdateLive();
        }

        /// <summary>The game was paused at this song time (the seconds around it don't count).</summary>
        public void AddPause(float songTime) => pauses.Add(songTime / speed);

        void UpdateLive()
        {
            double now = frames.T[frames.Count - 1];
            lastLive = now;
            if (now - frames.T[0] < LiveWindow)
            {
                lock (liveLock) live = new DanceLive { SongTime = (float)(now * speed) };
                return;
            }
            if (Interlocked.CompareExchange(ref liveBusy, 1, 0) != 0) return; // previous update still running
            frames.CopyTailTo(liveSnapshot, now - LiveWindow);
            if (livePauses.Length != pauses.Count) livePauses = pauses.ToArray();  // only when a pause was added
            if (liveJumps.Length != jumps.Count) liveJumps = jumps.ToArray();
            liveNow = now;
            if (LiveInBackground) ThreadPool.QueueUserWorkItem(liveCallback);
            else ComputeLive();
        }

        void ComputeLive()
        {
            try
            {
                liveWork.Reset();
                var m = DanceMath.Measure(liveSnapshot.Grid(liveNow - LiveWindow, liveNow, liveWork), false, livePauses, liveJumps,
                    walls, speed, gridPeriod, liveWork);
                var result = new DanceLive { SongTime = (float)(liveNow * speed), Ready = true, CountedFraction = m.CountedFraction };
                result.Level = DanceMath.Rank(m, DanceTables.Window);
                result.ShouldDrain = m.CountedFraction >= LiveMinCounted && !(result.Level >= DanceTables.LiveThreshold);
                lock (liveLock) live = result;
            }
            catch (Exception)
            {
                // a failed update keeps the previous state; the meter must never take the game down
            }
            finally { Interlocked.Exchange(ref liveBusy, 0); }
        }

        /// <summary>Raw measures of the trailing <see cref="LiveWindow"/> seconds, computed inline (what the live level is
        /// built from; used to build the reference windows). Null until a full window has been seen.</summary>
        public DanceMeasures WindowMeasures()
        {
            if (frames.Count == 0) return null;
            double now = frames.T[frames.Count - 1];
            if (now - frames.T[0] < LiveWindow) return null;
            var snap = new FrameBuffer(4096);
            frames.CopyTailTo(snap, now - LiveWindow);
            var work = new Workspace();
            return DanceMath.Measure(snap.Grid(now - LiveWindow, now, work), false, pauses.ToArray(), jumps.ToArray(), walls, speed,
                gridPeriod, work);
        }

        /// <summary>The score for everything fed so far (the full replay at the end of the level).</summary>
        public DanceResult Finish()
        {
            var result = new DanceResult { Valid = false, Score = double.NaN, VoteShare = double.NaN };
            if (frames.Count < MinFrames || frames.T[frames.Count - 1] - frames.T[0] < MinSeconds) return result;
            var work = new Workspace();
            var m = DanceMath.Measure(frames.Grid(frames.T[0], frames.T[frames.Count - 1], work), true, pauses.ToArray(),
                jumps.ToArray(), walls, speed, gridPeriod, work);
            result.Measures = m;
            result.Score = DanceMath.Rank(m, DanceTables.Song);
            if (double.IsNaN(result.Score)) return result;
            result.Valid = true;
            result.VoteShare = DanceTables.VoteShare(result.Score);
            return result;
        }
    }

    /// <summary>Frames as recorded (real-time seconds and 10 channels: head x y z, roll, left x y z, right x y z), and
    /// their resampling to the 50 Hz grid.</summary>
    internal sealed class FrameBuffer
    {
        public double[] T;
        public readonly double[][] Ch = new double[10][];
        public int Count;

        public FrameBuffer(int capacity)
        {
            T = new double[capacity];
            for (int c = 0; c < Ch.Length; c++) Ch[c] = new double[capacity];
        }

        public void Add(double t, double a, double b, double c, double d, double e, double f, double g, double h, double i, double j)
        {
            if (Count == T.Length) Grow(T.Length * 2);
            int n = Count++;
            T[n] = t; Ch[0][n] = a; Ch[1][n] = b; Ch[2][n] = c; Ch[3][n] = d; Ch[4][n] = e;
            Ch[5][n] = f; Ch[6][n] = g; Ch[7][n] = h; Ch[8][n] = i; Ch[9][n] = j;
        }

        void Grow(int capacity)
        {
            Array.Resize(ref T, capacity);
            for (int c = 0; c < Ch.Length; c++) Array.Resize(ref Ch[c], capacity);
        }

        /// <summary>Copies the frames from the last one at or before `from` (needed to interpolate) onwards.</summary>
        public void CopyTailTo(FrameBuffer dst, double from)
        {
            int lo = 0, hi = Count;
            while (lo < hi) { int mid = (lo + hi) >> 1; if (T[mid] < from) lo = mid + 1; else hi = mid; }
            int start = Math.Max(0, lo - 1), n = Count - start;
            if (dst.T.Length < n) dst.Grow(Math.Max(n, dst.T.Length * 2));
            Array.Copy(T, start, dst.T, 0, n);
            for (int c = 0; c < Ch.Length; c++) Array.Copy(Ch[c], start, dst.Ch[c], 0, n);
            dst.Count = n;
        }

        /// <summary>Resampled to the 50 Hz grid from tStart, like numpy arange(tStart, tEnd, 1/50) + interp.</summary>
        public GridData Grid(double tStart, double tEnd, Workspace w)
        {
            double step = 1.0 / DanceScorer.SampleRate;
            int n = (int)Math.Ceiling((tEnd - tStart) / step), last = Count - 1;
            var g = new GridData(w.D(n));
            for (int c = 0; c < g.Ch.Length; c++) g.Ch[c] = w.D(n);
            int j = 0;
            for (int k = 0; k < n; k++)
            {
                double x = tStart + k * step;
                g.T[k] = x;
                while (j + 1 <= last && T[j + 1] <= x) j++;
                for (int c = 0; c < Ch.Length; c++)
                {
                    var ch = Ch[c];
                    double v;
                    if (x <= T[0]) v = ch[0];
                    else if (j >= last) v = ch[last];
                    else
                    {
                        double t0 = T[j], t1 = T[j + 1];
                        v = x == t0 ? ch[j] : ch[j] + (ch[j + 1] - ch[j]) * (x - t0) / (t1 - t0);
                    }
                    g.Ch[c][k] = v;
                }
            }
            return g;
        }
    }

    internal sealed class GridData
    {
        public readonly double[] T;
        public readonly double[][] Ch = new double[10][];
        public GridData(double[] t) { T = t; }
    }

    /// <summary>Scratch arrays reused between computations of the same size: after the first live update the next
    /// ones allocate nothing. Arrays come back zeroed; Reset() before each computation.</summary>
    internal sealed class Workspace
    {
        sealed class Bucket<TItem> { public int Size, Used; public readonly List<TItem[]> Items = new List<TItem[]>(); }
        readonly List<Bucket<double>> doubles = new List<Bucket<double>>();
        readonly List<Bucket<bool>> bools = new List<Bucket<bool>>();

        public void Reset()
        {
            foreach (var b in doubles) b.Used = 0;
            foreach (var b in bools) b.Used = 0;
        }

        public double[] D(int n) => Rent(doubles, n);
        public bool[] B(int n) => Rent(bools, n);

        static TItem[] Rent<TItem>(List<Bucket<TItem>> buckets, int n)
        {
            Bucket<TItem> bucket = null;
            foreach (var b in buckets) if (b.Size == n) { bucket = b; break; }
            if (bucket == null) { bucket = new Bucket<TItem> { Size = n }; buckets.Add(bucket); }
            if (bucket.Used == bucket.Items.Count) bucket.Items.Add(new TItem[n]);
            var a = bucket.Items[bucket.Used++];
            Array.Clear(a, 0, n);
            return a;
        }
    }

    /// <summary>A reference distribution set: per-measure quantiles and the composite's quantiles.</summary>
    internal sealed class ReferenceSet
    {
        public double[] Tilt, BeatBounce, BeatLock, FreeSway, Sway, Steadiness, Composite;
    }

    internal static class DanceMath
    {
        const double FS = DanceScorer.SampleRate;

        // ---------------------------------------------------------------- scoring

        // weights fitted on the votes (analyze.DANCE): free sway counts double
        const double WTilt = 1, WBeatBounce = 1, WBeatLock = 1, WFreeSway = 2, WSway = 1, WSteadiness = 1;
        // sway without bounce is not dancing (analyze.BOUNCE_CM / BOUNCE_PENALTY): under BounceCm of beat-locked bounce
        // the composite loses up to BouncePenalty, linearly
        const double BounceCm = 0.3, BouncePenalty = 0.3;

        /// <summary>Weighted mean of each measure's rank in the reference, less the bounce penalty, then the
        /// composite's own rank.</summary>
        public static double Rank(DanceMeasures m, ReferenceSet r)
        {
            double sum = 0, w = 0;
            Add(ref sum, ref w, m.Tilt, r.Tilt, WTilt);
            Add(ref sum, ref w, m.BeatBounce, r.BeatBounce, WBeatBounce);
            Add(ref sum, ref w, m.BeatLock, r.BeatLock, WBeatLock);
            Add(ref sum, ref w, m.FreeSway, r.FreeSway, WFreeSway);
            Add(ref sum, ref w, m.Sway, r.Sway, WSway);
            Add(ref sum, ref w, m.Steadiness, r.Steadiness, WSteadiness);
            if (w == 0) return double.NaN;
            double composite = sum / w;
            if (m.BeatBounce < BounceCm) composite -= BouncePenalty * (1 - m.BeatBounce / BounceCm); // false for NaN
            return Percentile(r.Composite, composite);
        }

        static void Add(ref double sum, ref double w, double value, double[] table, double weight)
        {
            if (double.IsNaN(value)) return;
            sum += weight * Percentile(table, value); w += weight;
        }

        /// <summary>Share of the reference strictly below x, from a quantile table (q[k] = quantile k / (n - 1)).</summary>
        public static double Percentile(double[] q, double x)
        {
            int n = q.Length - 1;
            if (x <= q[0]) return 0;
            if (x > q[n]) return 1;
            int lo = 0, hi = n;                       // largest k with q[k] < x
            while (hi - lo > 1) { int mid = (lo + hi) >> 1; if (q[mid] < x) lo = mid; else hi = mid; }
            double span = q[lo + 1] - q[lo];
            double frac = span > 0 ? (x - q[lo]) / span : 1;
            return Math.Min(1, (lo + Math.Min(1, frac)) / n);
        }

        // ---------------------------------------------------------------- measures (features.py)

        public static DanceMeasures Measure(GridData g, bool final, double[] pauses, double[] jumps,
            DanceWall[] walls, double speed, double gridPeriod, Workspace w)
        {
            int n = g.T.Length;
            double[] T = g.T, hx = g.Ch[0], hy = g.Ch[1], hz = g.Ch[2];
            var valid = w.B(n);
            for (int k = 0; k < n; k++) valid[k] = true;
            foreach (var p in pauses)
                for (int k = 0; k < n; k++) if (Math.Abs(T[k] - p) <= 1.5) valid[k] = false;
            if (final)
                for (int k = 0; k < n; k++) if (T[k] >= T[n - 1] - DanceScorer.EndSeconds) valid[k] = false;
            foreach (var jt in jumps)
            {
                if (jt < T[0] - 1 || jt > T[n - 1] + 1) continue;
                for (int k = 0; k < n; k++) if (Math.Abs(T[k] - jt) <= 0.5) valid[k] = false;
            }
            // head moving faster than a person can move it: tracking error
            var gx = Gradient(Filters.FiltFilt(Filters.Low6, hx, w), w);
            var gy = Gradient(Filters.FiltFilt(Filters.Low6, hy, w), w);
            var gz = Gradient(Filters.FiltFilt(Filters.Low6, hz, w), w);
            bool prevFast = false;
            for (int k = 0; k < n; k++)
            {
                bool fast = Math.Sqrt(gx[k] * gx[k] + gy[k] * gy[k] + gz[k] * gz[k]) > 4.0;
                if (fast && !prevFast)
                    for (int i = Math.Max(0, k - 15); i < Math.Min(n, k + 15); i++) valid[i] = false;
                prevFast = fast;
            }
            // walls in the way of the player's usual head position: that movement is forced, not danced
            if (walls.Length > 0)
            {
                double mx = Median(hx, valid, w), my = Median(hy, valid, w);
                if (!double.IsNaN(mx))
                {
                    var forced = w.B(n);
                    foreach (var wall in walls)
                    {
                        if (!(wall.X0 < mx + 0.3 && wall.X1 > mx - 0.3 && wall.Y0 < my + 0.1 && wall.Y1 > my - 0.2)) continue;
                        int i0 = LowerBound(T, wall.StartTime / speed - 0.6), i1 = LowerBound(T, wall.EndTime / speed + 0.3);
                        for (int i = i0; i < i1; i++) forced[i] = true;
                    }
                    for (int k = 0; k < n; k++) if (forced[k]) valid[k] = false;
                }
            }
            int counted = 0;
            for (int k = 0; k < n; k++) if (valid[k]) counted++;
            var m = new DanceMeasures
            {
                Tilt = double.NaN, BeatBounce = double.NaN, BeatLock = double.NaN, FreeSway = double.NaN,
                Sway = double.NaN, Steadiness = double.NaN, CountedFraction = n > 0 ? (double)counted / n : 0
            };
            if (counted == 0) return m;

            // intentional movement only: steep 3.5 Hz low-pass removes swing shake and tracker jitter
            var sx = Filters.FiltFilt(Filters.Intent, hx, w); var sy = Filters.FiltFilt(Filters.Intent, hy, w);
            var sz = Filters.FiltFilt(Filters.Intent, hz, w); var roll = Filters.FiltFilt(Filters.Intent, g.Ch[3], w);
            var vx = Gradient(sx, w); var vy = Gradient(sy, w); var vz = Gradient(sz, w);

            var speeds = w.D(n);
            double meanSpeed = 0;
            for (int k = 0, c = 0; k < n; k++)
            {
                if (!valid[k]) continue;
                double s = Math.Min(Math.Sqrt(vx[k] * vx[k] + vy[k] * vy[k] + vz[k] * vz[k]), 3.0);
                speeds[c++] = s; meanSpeed += s;
            }
            meanSpeed /= counted;
            double p99 = Quantile(speeds, counted, 0.99);
            m.Steadiness = p99 > 0 ? meanSpeed / p99 : double.NaN;

            m.Sway = 100 * RmsPair(Filters.FiltFilt(Filters.Band02, sx, w), Filters.FiltFilt(Filters.Band02, sz, w), valid);
            m.Tilt = RmsPair(Filters.FiltFilt(Filters.Band03, roll, w), null, valid);

            // sway the hands don't explain: regress head velocity on the hands' velocities within +-0.2 s
            var hand = new double[6][];
            for (int c = 0; c < 6; c++)
            {
                var gr = Gradient(Filters.FiltFilt(Filters.Low6, g.Ch[4 + c], w), w);
                for (int k = 0; k < n; k++) gr[k] = valid[k] ? Clip(gr[k], 15) : 0;
                hand[c] = gr;
            }
            var yx = w.D(n); var yz = w.D(n);
            for (int k = 0; k < n; k++) { yx[k] = valid[k] ? Clip(vx[k], 3) : 0; yz[k] = valid[k] ? Clip(vz[k], 3) : 0; }
            var rx = w.D(n); var rz = w.D(n);
            SwingResidual(hand, yx, yz, valid, rx, rz, w);
            double cx = 0, cz = 0;
            for (int k = 0; k < n; k++)
            {
                cx += valid[k] ? rx[k] : 0; cz += valid[k] ? rz[k] : 0;
                rx[k] = cx / FS; rz[k] = cz / FS;   // back to positions; the band-pass removes integration drift
            }
            m.FreeSway = 100 * RmsPair(Filters.FiltFilt(Filters.Band02, rx, w), Filters.FiltFilt(Filters.Band02, rz, w), valid);

            // bounce in time with the beat (the note grid)
            if (!double.IsNaN(gridPeriod))
            {
                var v = w.D(n);
                for (int k = 0; k < n; k++) v[k] = valid[k] ? vy[k] : 0;
                double amp, ratio, f;
                BeatLock(v, gridPeriod, out amp, out ratio, out f);
                m.BeatBounce = double.IsNaN(f) ? 0 : 100 * amp / (2 * Math.PI * f);
                m.BeatLock = ratio;
            }
            return m;
        }

        static readonly int[] Lags = { -10, -8, -6, -4, -2, 0, 2, 4, 6, 8, 10 };
        const int Regressors = 11 * 6 + 1;

        /// <summary>Least squares of yx, yz on the hands' velocities at 11 lags (+ intercept), over valid rows away
        /// from the edges; writes the residual for every row (features.swing_residual, np.roll wrap-around kept).</summary>
        static void SwingResidual(double[][] hand, double[] yx, double[] yz, bool[] valid, double[] rx, double[] rz, Workspace w)
        {
            int n = yx.Length, p = Regressors;
            var a = w.D(p * p); var bx = w.D(p); var bz = w.D(p); var row = w.D(p);
            for (int i = 10; i < n - 10; i++)
            {
                if (!valid[i]) continue;
                FillRow(hand, i, n, row);
                for (int r = 0; r < p; r++)
                {
                    double v = row[r];
                    if (v == 0) continue;
                    int off = r * p;
                    for (int c = r; c < p; c++) a[off + c] += v * row[c];
                    bx[r] += v * yx[i]; bz[r] += v * yz[i];
                }
            }
            for (int r = 0; r < p; r++) for (int c = 0; c < r; c++) a[r * p + c] = a[c * p + r];
            Cholesky(a, p);
            var cx = w.D(p); var cz = w.D(p); var tmp = w.D(p);
            Solve(a, bx, p, tmp, cx); Solve(a, bz, p, tmp, cz);
            for (int i = 0; i < n; i++)
            {
                FillRow(hand, i, n, row);
                double px = 0, pz = 0;
                for (int c = 0; c < p; c++) { px += row[c] * cx[c]; pz += row[c] * cz[c]; }
                rx[i] = yx[i] - px; rz[i] = yz[i] - pz;
            }
        }

        static void FillRow(double[][] hand, int i, int n, double[] row)
        {
            int c = 0;
            foreach (var lag in Lags)
            {
                int j = ((i + lag) % n + n) % n;
                for (int h = 0; h < 6; h++) row[c++] = hand[h][j];
            }
            row[c] = 1;
        }

        /// <summary>In-place Cholesky (lower) with a tiny ridge, for the rank-deficient cases lstsq would also handle.</summary>
        static void Cholesky(double[] a, int p)
        {
            double trace = 0;
            for (int i = 0; i < p; i++) trace += a[i * p + i];
            double ridge = 1e-10 * Math.Max(trace / p, 1e-12);
            for (int i = 0; i < p; i++) a[i * p + i] += ridge;
            for (int j = 0; j < p; j++)
            {
                double s = a[j * p + j];
                for (int k = 0; k < j; k++) s -= a[j * p + k] * a[j * p + k];
                double d = Math.Sqrt(Math.Max(s, 1e-300));
                a[j * p + j] = d;
                for (int i = j + 1; i < p; i++)
                {
                    double v = a[i * p + j];
                    for (int k = 0; k < j; k++) v -= a[i * p + k] * a[j * p + k];
                    a[i * p + j] = v / d;
                }
            }
        }

        static void Solve(double[] l, double[] b, int p, double[] y, double[] x)
        {
            for (int i = 0; i < p; i++)
            {
                double v = b[i];
                for (int k = 0; k < i; k++) v -= l[i * p + k] * y[k];
                y[i] = v / l[i * p + i];
            }
            for (int i = p - 1; i >= 0; i--)
            {
                double v = y[i];
                for (int k = i + 1; k < p; k++) v -= l[k * p + i] * x[k];
                x[i] = v / l[i * p + i];
            }
        }

        // ---------------------------------------------------------------- beat (features.grid_period / beat_lock)

        /// <summary>Longest note-grid period that still explains the note times, by phase concentration in 20 s chunks.
        /// Runs once per level (about 0.1 s).</summary>
        public static double GridPeriod(List<double> noteTimes)
        {
            var set = new SortedSet<double>();
            foreach (var x in noteTimes) set.Add(Math.Round(x, 3, MidpointRounding.ToEven));
            var times = new List<double>(set);
            if (times.Count < 30) return double.NaN;
            const int periods = 2260;                 // numpy arange(0.12, 1.25, 0.0005)
            var acc = new double[periods];
            double wsum = 0, first = times[0], last = times[times.Count - 1];
            int chunks = (int)Math.Ceiling((last - first) / 20.0);
            var tc = new List<double>();
            for (int c = 0; c < chunks; c++)
            {
                double c0 = first + c * 20.0;
                tc.Clear();
                foreach (var x in times) if (x >= c0 && x < c0 + 20) tc.Add(x);
                if (tc.Count < 8) continue;
                for (int k = 0; k < periods; k++)
                {
                    double per = 0.12 + k * 0.0005, re = 0, im = 0;
                    foreach (var x in tc) { double ph = 2 * Math.PI * x / per; re += Math.Cos(ph); im += Math.Sin(ph); }
                    acc[k] += Math.Sqrt(re * re + im * im);   // = count * |mean phasor|
                }
                wsum += tc.Count;
            }
            if (wsum == 0) return double.NaN;
            int good = -1, best = 0;
            for (int k = 0; k < periods; k++)
            {
                if (acc[k] / wsum > 0.8) good = k;
                if (acc[k] > acc[best]) best = k;
            }
            return 0.12 + (good >= 0 ? good : best) * 0.0005;
        }

        static readonly double[] BeatMultiples = { 0.25, 0.5, 1, 2, 3, 4, 6, 8 };

        /// <summary>Strongest note-grid harmonic in v, as power above the non-harmonic neighbours (f*0.82, f*1.18).</summary>
        static void BeatLock(double[] v, double p0, out double amp, out double ratio, out double freq)
        {
            double bestExcess = 0, bestRatio = double.NaN, bestF = double.NaN;
            foreach (var mul in BeatMultiples)
            {
                double f = 1 / (mul * p0);
                if (f < 0.4 || f > 3.5) continue;
                double p = BeatPower(v, f), pn = (BeatPower(v, f * 0.82) + BeatPower(v, f * 1.18)) / 2;
                if (!double.IsNaN(p) && !double.IsNaN(pn) && p - pn > bestExcess)
                {
                    bestExcess = p - pn; bestRatio = p / Math.Max(pn, 1e-12); bestF = f;
                }
            }
            if (bestExcess > 0) { amp = Math.Sqrt(2 * bestExcess); ratio = bestRatio; freq = bestF; }
            else { amp = 0; ratio = 1; freq = double.NaN; }
        }

        const int BeatWindow = 400;                   // 8 s at 50 Hz
        static readonly double[] Hann = MakeHann(BeatWindow, out HannSum);
        static readonly double HannSum;

        static double[] MakeHann(int n, out double sum)
        {
            var h = new double[n];
            sum = 0;
            for (int k = 0; k < n; k++) { h[k] = 0.5 - 0.5 * Math.Cos(2 * Math.PI * k / (n - 1)); sum += h[k]; }
            return h;
        }

        /// <summary>Mean power (A^2/2) of v at frequency f over 8 s Hann windows, half overlapping.</summary>
        static double BeatPower(double[] v, double f)
        {
            const int n = BeatWindow;
            if (v.Length < n || !(f > 0.2 && f < 6)) return double.NaN;
            // the phasor exp(-2 pi i f k / FS) is advanced by one fixed rotation per sample instead of sin/cos each time
            double stepRe = Math.Cos(-2 * Math.PI * f / FS), stepIm = Math.Sin(-2 * Math.PI * f / FS);
            double total = 0; int windows = 0;
            for (int s = 0; s + n <= v.Length; s += n / 2)
            {
                double mean = 0;
                for (int k = 0; k < n; k++) mean += v[s + k];
                mean /= n;
                double re = 0, im = 0, cr = 1, ci = 0;
                for (int k = 0; k < n; k++)
                {
                    double x = (v[s + k] - mean) * Hann[k];
                    re += x * cr; im += x * ci;
                    double nr = cr * stepRe - ci * stepIm;
                    ci = cr * stepIm + ci * stepRe; cr = nr;
                }
                total += 2 * (re * re + im * im) / (HannSum * HannSum);
                windows++;
            }
            return total / windows;
        }

        // ---------------------------------------------------------------- small helpers

        /// <summary>Roll (head tilt) in degrees from a Unity quaternion, as features.quat_ypr.</summary>
        public static double Roll(double x, double y, double z, double w)
        {
            double ux = 2 * (x * y - w * z), uy = 1 - 2 * (x * x + z * z);
            return Math.Atan2(ux, uy) * 180 / Math.PI;
        }

        /// <summary>numpy.gradient with spacing 1/FS (one-sided at the ends).</summary>
        static double[] Gradient(double[] x, Workspace w)
        {
            int n = x.Length;
            var g = w.D(n);
            if (n < 2) return g;
            g[0] = (x[1] - x[0]) * FS; g[n - 1] = (x[n - 1] - x[n - 2]) * FS;
            for (int i = 1; i < n - 1; i++) g[i] = (x[i + 1] - x[i - 1]) * FS / 2;
            return g;
        }

        static double RmsPair(double[] a, double[] b, bool[] valid)
        {
            double s = 0; int c = 0;
            for (int k = 0; k < a.Length; k++)
            {
                if (!valid[k]) continue;
                s += a[k] * a[k] + (b == null ? 0 : b[k] * b[k]); c++;
            }
            return c > 0 ? Math.Sqrt(s / c) : double.NaN;
        }

        static double Clip(double x, double lim) => x > lim ? lim : x < -lim ? -lim : x;

        static double Median(double[] x, bool[] valid, Workspace w)
        {
            var a = w.D(x.Length);
            int n = 0;
            for (int k = 0; k < x.Length; k++) if (valid[k]) a[n++] = x[k];
            if (n == 0) return double.NaN;
            Array.Sort(a, 0, n);
            return n % 2 == 1 ? a[n / 2] : (a[n / 2 - 1] + a[n / 2]) / 2;
        }

        /// <summary>numpy.percentile (linear) of the first `count` values; sorts them in place.</summary>
        static double Quantile(double[] values, int count, double q)
        {
            Array.Sort(values, 0, count);
            double pos = q * (count - 1);
            int lo = (int)Math.Floor(pos), hi = Math.Min(lo + 1, count - 1);
            return values[lo] + (pos - lo) * (values[hi] - values[lo]);
        }

        static int LowerBound(double[] a, double x)
        {
            int lo = 0, hi = a.Length;
            while (lo < hi) { int mid = (lo + hi) >> 1; if (a[mid] < x) lo = mid + 1; else hi = mid; }
            return lo;
        }
    }

    /// <summary>Zero-phase Butterworth filters at 50 Hz, exactly as scipy.signal.sosfiltfilt (odd padding).</summary>
    internal static class Filters
    {
        internal sealed class Sos
        {
            public readonly double[] S, Zi; public readonly int PadLen;
            public Sos(double[] s, double[] zi, int padLen) { S = s; Zi = zi; PadLen = padLen; }
        }

        // butter(8, 3.5, 'lowpass', fs=50): intentional head movement only
        public static readonly Sos Intent = new Sos(new[] {
            1.994750644033132e-06, 3.989501288066264e-06, 1.994750644033132e-06, 1.0, -1.2765636139118355, 0.4108371433332852,
            1.0, 2.0, 1.0, 1.0, -1.3365021985616892, 0.4770802828222039,
            1.0, 2.0, 1.0, 1.0, -1.463469868226014, 0.6174028663681828,
            1.0, 2.0, 1.0, 1.0, -1.6708631565737775, 0.8466105229944219 }, new[] {
            5.742874563637306e-05, -2.2418628814685046e-05, 0.0016314089430145985, -0.0007472393220634114,
            0.04224600916586607, -0.02543589950689627, 0.9560631583948387, -0.8026736813892607 }, 27);
        // butter(4, 6, 'lowpass', fs=50): hands, and the tracking-glitch speed check
        public static readonly Sos Low6 = new Sos(new[] {
            0.00891445723946302, 0.01782891447892604, 0.00891445723946302, 1.0, -0.8931036327062872, 0.22516058868743402,
            1.0, 2.0, 1.0, 1.0, -1.1552915050582222, 0.5848302129885163 }, new[] {
            0.09847021974311047, -0.015264339845943175, 0.8926153230174261, -0.47744553600594264 }, 15);
        // butter(2, [0.2, 3], 'bandpass', fs=50): sway
        public static readonly Sos Band02 = new Sos(new[] {
            0.02463060804906882, 0.04926121609813764, 0.02463060804906882, 1.0, -1.52773348395035, 0.6296636058722758,
            1.0, -2.0, 1.0, 1.0, -1.9650630430819829, 0.9657628068672337 }, new[] {
            0.9419377658388716, -0.5839823195753139, -0.9665683738879405, 0.9665683738879405 }, 15);
        // butter(2, [0.3, 3], 'bandpass', fs=50): tilt
        public static readonly Sos Band03 = new Sos(new[] {
            0.023074421716934572, 0.046148843433869144, 0.023074421716934572, 1.0, -1.5526244517732186, 0.6512722944212291,
            1.0, -2.0, 1.0, 1.0, -1.9487924351826795, 0.9504301927924739 }, new[] {
            0.912553610181031, -0.5862741933420725, -0.9356280318979657, 0.9356280318979657 }, 15);

        public static double[] FiltFilt(Sos f, double[] x, Workspace w)
        {
            int n = x.Length, pad = Math.Min(f.PadLen, Math.Max(0, n - 1));
            var y = w.D(n);
            if (n == 0) return y;
            int m = n + 2 * pad;
            var e = w.D(m);
            for (int i = 0; i < pad; i++) e[i] = 2 * x[0] - x[pad - i];
            for (int i = 0; i < n; i++) e[pad + i] = x[i];
            for (int i = 0; i < pad; i++) e[pad + n + i] = 2 * x[n - 1] - x[n - 2 - i];
            Run(f, e, e[0]);
            Array.Reverse(e);
            Run(f, e, e[0]);
            Array.Reverse(e);
            Array.Copy(e, pad, y, 0, n);
            return y;
        }

        /// <summary>In-place sosfilt with every section's initial state = zi * x0, as sosfiltfilt passes it
        /// (sosfilt_zi already holds each section's steady state for a unit step into the cascade).</summary>
        static void Run(Sos f, double[] x, double x0)
        {
            int sections = f.S.Length / 6;
            for (int s = 0; s < sections; s++)
            {
                double b0 = f.S[s * 6], b1 = f.S[s * 6 + 1], b2 = f.S[s * 6 + 2], a1 = f.S[s * 6 + 4], a2 = f.S[s * 6 + 5];
                double z1 = f.Zi[s * 2] * x0, z2 = f.Zi[s * 2 + 1] * x0;
                for (int i = 0; i < x.Length; i++)
                {
                    double xi = x[i], yi = b0 * xi + z1;
                    z1 = b1 * xi - a1 * yi + z2;
                    z2 = b2 * xi - a2 * yi;
                    x[i] = yi;
                }
            }
        }
    }

